const {chromium} = require(process.env.FLEET_PLAYWRIGHT_MODULE);
const assert = require('node:assert/strict');
const fs = require('node:fs');
const [origin, mailbox] = process.argv.slice(2);
(async () => {
  const browser = await chromium.launch({channel: process.env.FLEET_BROWSER_CHANNEL || 'chrome', headless: true});
  try {
    const page = await browser.newPage({viewport: {width: 390, height: 844}});
    page.setDefaultTimeout(7000);
    const errors = []; page.on('pageerror', error => errors.push(error.message));
    await page.goto(origin + '/account');
    await page.waitForURL('**/login?**');
    if (process.env.FLEET_SCREENSHOTS) {
      fs.mkdirSync(process.env.FLEET_SCREENSHOTS, {recursive: true});
      await page.screenshot({path: process.env.FLEET_SCREENSHOTS + '/login-mobile.png', fullPage: true});
      await page.setViewportSize({width: 1440, height: 1000});
      await page.screenshot({path: process.env.FLEET_SCREENSHOTS + '/login-desktop.png', fullPage: true});
      await page.setViewportSize({width: 390, height: 844});
    }
    await page.getByRole('button', {name: '注册账号', exact: true}).click();
    await page.getByLabel('邮箱', {exact: true}).fill('browser@example.test');
    await page.getByLabel('昵称', {exact: true}).fill('Browser');
    await page.getByRole('button', {name: '发送验证码', exact: true}).click();
    await page.getByText('验证码请求已受理。请查看邮箱；若未收到，请稍后重试或联系管理员。', {exact: true}).waitFor();
    const code = JSON.parse(fs.readFileSync(mailbox, 'utf8')).at(-1)[2];
    await page.getByLabel('邮箱验证码', {exact: true}).fill(code);
    await page.getByLabel('密码', {exact: true}).fill('browser-password-123!');
    await page.getByLabel('确认密码', {exact: true}).fill('browser-password-123!');
    await page.getByRole('button', {name: '验证并注册', exact: true}).click();
    await page.getByText('注册成功，请登录。', {exact: true}).waitFor();
    await page.getByLabel('邮箱', {exact: true}).fill('browser@example.test');
    await page.getByLabel('密码', {exact: true}).fill('wrong-password-123!');
    await page.getByRole('button', {name: '登录', exact: true}).click();
    await page.getByText('邮箱或密码错误', {exact: true}).waitFor();
    await page.getByLabel('密码', {exact: true}).fill('browser-password-123!');
    await page.getByRole('button', {name: '登录', exact: true}).click();
    await page.waitForURL('**/account');
    await page.getByRole('heading', {name: '个人资料', exact: true}).waitFor();
    assert.equal(await page.locator('[data-nav=fleet]').isVisible(), false);
    await page.getByLabel('昵称', {exact: true}).fill('Changed');
    await page.getByRole('button', {name: '保存昵称', exact: true}).click();
    await page.getByText('昵称已保存', {exact: true}).waitFor();
    await page.getByLabel('当前密码', {exact: true}).fill('browser-password-123!');
    await page.getByLabel('新密码', {exact: true}).fill('new-browser-password-123!');
    await page.getByLabel('确认新密码', {exact: true}).fill('new-browser-password-123!');
    await page.getByRole('button', {name: '修改密码并退出所有设备', exact: true}).click();
    await page.waitForURL('**/login?**');
    await page.getByRole('button', {name: '忘记密码', exact: true}).click();
    await page.getByRole('heading', {name: '找回密码', exact: true}).waitFor();
    assert.equal(await page.getByLabel('邮箱验证码', {exact: true}).isVisible(), true);
    await page.getByLabel('邮箱', {exact: true}).fill('browser@example.test');
    await page.getByRole('button', {name: '发送验证码', exact: true}).click();
    await page.getByText('验证码请求已受理。请查看邮箱；若未收到，请稍后重试或联系管理员。', {exact: true}).waitFor();
    const resetCode = JSON.parse(fs.readFileSync(mailbox, 'utf8')).at(-1)[2];
    await page.getByLabel('邮箱验证码', {exact: true}).fill(resetCode);
    await page.getByLabel('新密码', {exact: true}).fill('reset-browser-password-123!');
    await page.getByLabel('确认密码', {exact: true}).fill('reset-browser-password-123!');
    await page.getByRole('button', {name: '重置密码', exact: true}).click();
    await page.getByText('密码已重置，请使用新密码登录。', {exact: true}).waitFor();
    await page.getByLabel('邮箱', {exact: true}).fill('browser@example.test');
    await page.getByLabel('密码', {exact: true}).fill('reset-browser-password-123!');
    await page.getByRole('button', {name: '登录', exact: true}).click();
    await page.waitForURL('**/account');
    await page.goto(origin + '/account?history=1');
    await page.getByRole('button', {name: '退出所有会话', exact: true}).click();
    await page.waitForURL('**/login?**');
    await page.goBack();
    await page.waitForURL('**/login?**');
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth), false);
    assert.deepEqual(errors, []);
    console.log('PASS: email registration, password login, account settings, password change, logout and page guards');
  } finally { await browser.close(); }
})().catch(error => {console.error(error); process.exitCode = 1;});
